import { strict as assert } from "node:assert"
// @ts-ignore dist is generated by the package build before this smoke test.
import { Circuit, assembly } from "../../dist"
import { convertCircuitJsonToAssemblyBom } from "circuit-json-to-bom-csv"

const circuit = new Circuit()
circuit.add(
  <assembly.device>
    <assembly.subassembly name="housing" bomQuantity={2}>
      <assembly.part
        name="screws"
        bomQuantity={4}
        purchaseUrls={["https://store.example/screws"]}
      />
    </assembly.subassembly>
  </assembly.device>,
)
await circuit.renderUntilSettled()
const [housing] = await convertCircuitJsonToAssemblyBom({
  circuitJson: circuit.getCircuitJson(),
})
assert.equal(housing.total_quantity, 2)
assert.equal(housing.children[0].total_quantity, 8)
assert.deepEqual(housing.children[0].purchase_urls, [
  "https://store.example/screws",
])
console.log("Built package renders assembly TSX through the BOM converter")
